package hk.edu.polyu.comp.comp2021.crobs.model;

/** A Crobs user. IDs are unique and generated by {@link IdGenerator}. */
public class User {

    private final String id;
    private String name;
    private Role role;

    /**
     * Creates a user.
     *
     * @param id   the unique user ID
     * @param name the full name of the user
     * @param role the access level of the user
     * @throws CrobsException.MalformedCommandException when an argument is null or blank
     */
    public User(String id, String name, Role role) {
        if (id == null || id.trim().isEmpty()) {
            throw new CrobsException.MalformedCommandException("User ID cannot be empty.");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new CrobsException.MalformedCommandException("User name cannot be empty.");
        }
        if (role == null) {
            throw new CrobsException.MalformedCommandException("User role cannot be null.");
        }
        this.id = id.trim();
        this.name = name.trim();
        this.role = role;
    }

    /** @return the unique user ID */
    public String getId() { return id; }

    /** @return the full name of the user */
    public String getName() { return name; }

    /** @return the access level of the user */
    public Role getRole() { return role; }

    /**
     * Changes the access level of the user (REQ4).
     *
     * @param role the new access level
     * @throws CrobsException.MalformedCommandException when the role is null
     */
    public void setRole(Role role) {
        if (role == null) {
            throw new CrobsException.MalformedCommandException("User role cannot be null.");
        }
        this.role = role;
    }

    /** @return true when the user may run admin commands (admin or superadmin) */
    public boolean isAdmin() {
        return role == Role.ADMIN || role == Role.SUPERADMIN;
    }

    @Override
    public String toString() {
        return String.format("%s | %s | %s", id, name, role);
    }
}
